import { readFileSync, writeFileSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const __dirname = dirname(fileURLToPath(import.meta.url));
const cssPath = resolve(__dirname, "..", "src", "styles.css");
const outPath = resolve(__dirname, "..", "src", "styleContent.ts");

const css = readFileSync(cssPath, "utf-8");

const content = [
  "// @generated by scripts/generate-style-content.mjs — do not edit directly.",
  "// Run `node scripts/generate-style-content.mjs` or the package build to regenerate.",
  "",
  "export const viewerStyles = " + JSON.stringify(css) + ";",
  "",
].join("\n");

writeFileSync(outPath, content, "utf-8");

console.log("Generated src/styleContent.ts from src/styles.css");
